CREATE TABLE admins(id VARCHAR(36) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE admin_sessions(token_hash CHAR(64) PRIMARY KEY,admin_id VARCHAR(36) NOT NULL,expires_at BIGINT NOT NULL,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE,INDEX sessions_expiry(expires_at));
CREATE TABLE login_limits(identifier CHAR(64) PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,window_start BIGINT NOT NULL);
CREATE TABLE upload_intents(id VARCHAR(36) PRIMARY KEY,admin_id VARCHAR(36) NOT NULL,name VARCHAR(150) NOT NULL,mime VARCHAR(100) NOT NULL,size INT NOT NULL,expires_at BIGINT NOT NULL,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE);
